@js:// ================= manhuagui 阅读页解码器 =================
// 阅读页里那段 packer 是**诱饵**（第 4 个参数用 '…'['splic'](...)，浏览器里也会抛错），
// 真数据是 packer 的第 1 个参数（payload）+ 第 4 个参数（lz-string 压缩的关键字表）。
// 流程：lz-string 解压关键字表 → 按 | 切开 → 生成 token 字典 → 替换 payload 里的 token
//       → 得到 SMH.imgData({...}) / SMH.reader({...})，里面就有 files/path/images 和签名 e/m。
// 参考实现：github.com/lanyeeee/manhuagui-downloader-wails 的 backend/decoder/decoder.go
function mhgDecode(s) {
  var m = s.match(/}\('([\s\S]*?)',(\d+),(\d+),'([\w|+\/=]*)'/);
  if (!m) return [];
  var payload = m[1], a = parseInt(m[2], 10), c = parseInt(m[3], 10), blob = m[4];
  var K = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=", rev = {}, q;
  for (q = 0; q < K.length; q++) rev[K.charAt(q)] = q;

  function lz(b) {
    var dic = [], enl = 4, ds = 4, nb = 3, entry = "", res = [], w, x, d, rv;
    d = { v: rev[b.charAt(0)] || 0, p: 32, i: 1 };
    for (q = 0; q < 3; q++) dic[q] = q;
    function rb(n) {
      var t = 0, mm = Math.pow(2, n), pp = 1;
      while (pp != mm) {
        rv = d.v & d.p;
        d.p >>= 1;
        if (d.p == 0) { d.p = 32; d.v = rev[b.charAt(d.i++)] || 0; }
        t += (rv > 0 ? 1 : 0) * pp;
        pp <<= 1;
      }
      return t;
    }
    x = rb(2);
    if (x == 0) { w = String.fromCharCode(rb(8)); }
    else if (x == 1) { w = String.fromCharCode(rb(16)); }
    else { return ""; }
    dic[3] = w;
    res.push(w);
    while (true) {
      if (d.i > b.length) return "";
      x = rb(nb);
      if (x == 0) { dic[ds] = String.fromCharCode(rb(8)); x = ds; ds++; enl--; }
      else if (x == 1) { dic[ds] = String.fromCharCode(rb(16)); x = ds; ds++; enl--; }
      else if (x == 2) return res.join("");
      if (enl == 0) { enl = Math.pow(2, nb); nb++; }
      entry = dic[x] ? dic[x] : (x == ds ? w + w.charAt(0) : null);
      if (entry === null) return "";
      res.push(entry);
      dic[ds] = w + entry.charAt(0);
      ds++;
      enl--;
      w = entry;
      if (enl == 0) { enl = Math.pow(2, nb); nb++; }
    }
  }

  var plain = lz(blob);
  if (!plain) return [];
  var data = plain.split("|");
  function ee(n) {
    var cc = n % a;
    var ch = (cc > 35 ? String.fromCharCode(cc + 29) : cc.toString(36));
    if (n < a) return ch;
    return ee(parseInt(n / a, 10)) + ch;
  }
  var dict = {}, i, kk;
  for (i = c - 1; i >= 0; i--) {
    kk = ee(i);
    dict[kk] = (data[i] === "" || data[i] === undefined) ? kk : data[i];
  }
  var out = payload.replace(/\b\w+\b/g, function (t) {
    return dict[t] !== undefined ? dict[t] : t;
  });

  var pe = out.match(/"e":(\d+)/), pm = out.match(/"m":"([^"]*)"/);
  if (!pe || !pm) return [];
  var paths = [], im = out.match(/"images":\[([^\]]*)\]/), pt = out.match(/"path":"([^"]*)"/), fl;
  if (im) {
    paths = im[1].replace(/"/g, "").split(",");
  } else if (pt) {
    fl = out.match(/"files":\[([^\]]*)\]/);
    if (!fl) return [];
    fl = fl[1].replace(/"/g, "").split(",");
    for (i = 0; i < fl.length; i++) paths.push(pt[1] + fl[i]);
  } else {
    return [];
  }
  var urls = [];
  for (i = 0; i < paths.length; i++) {
    // 路径里的中文要转义，但已经 %XX 过的部分不能二次转义 —— 所以只动非 ASCII
    var p = paths[i].replace(/[^\x00-\x7F]/g, function (ch) { return encodeURIComponent(ch); });
    urls.push("https://i.hamreus.com" + p + "?e=" + pe[1] + "&m=" + pm[1]);
  }
  return urls;
}
